insert into public.people (id, slug, name, native_name, occupations, about, visible_from, sources) values
  (1, 'Natsuki_Takuya', 'Natsuki Takuya', null, array['Manga artist', 'Original creator']::text[], 'Manga artist and creator of Impact of Eden. Takuya''s writing is known for women whose authority comes from stillness and composure, a philosophy fans credit for the way the 2013 anime frames its female cast.', null, array['Lumine StarWorks YAL development brief (established production data)', 'AniFanWiki, "Impact of Eden (2013)" (last edited Oct 8, 2013)', 'YAL Impact of Eden Episode 1 Discussion (archived Oct 9, 2013)']::text[]),
  (2, 'Kaihatsu_Miura', 'Kaihatsu Miura', null, array['Director']::text[], 'Director known for dense, no-padding pacing. Directed Sinful Apex at Flow Pictures before moving to Studio Burst for Impact of Eden.', null, array['Lumine StarWorks YAL development brief (established production data)', 'SakugaThread, "Impact of Eden EP1 Sakuga Megathread" (Oct 6, 2013)', 'YAL Impact of Eden Episode 1 Discussion, page 4 (staff credit roundup)']::text[]),
  (3, 'Keito_Kisaragi', 'Keito Kisaragi', null, array['Series composition', 'Writer']::text[], 'Writer known for emotional through-lines and political tension.', null, array['Lumine StarWorks YAL development brief (established production data)', 'YAL Impact of Eden Episode 1 Discussion, page 4 (staff credit roundup)']::text[]),
  (4, 'Lio_Haraguchi', 'Lio Haraguchi', null, array['Character designer', 'Chief animation director']::text[], 'Character designer and chief animation director. Known for keeping faces on-model during chaotic action.', null, array['Lumine StarWorks YAL development brief (established production data)', 'AniFanWiki, "Impact of Eden (2013)" (last edited Oct 8, 2013)', 'YAL Impact of Eden Episode 1 Discussion, page 4 (staff credit roundup)']::text[]),
  (5, 'Tomoe_Suzuhara', 'Tomoe Suzuhara', null, array['Storyboard artist']::text[], 'Storyboard artist known for long-take action and silhouette-driven fight layouts. Leads storyboards and pacing on Impact of Eden.', null, array['Lumine StarWorks YAL development brief (established production data)', 'SakugaThread, "Impact of Eden EP1 Sakuga Megathread" (Oct 6, 2013)', 'AniWire, "''Impact of Eden'' Premiere Review" (Oct 6, 2013)']::text[]),
